# LOGIN
# ========================================
# This route handles both displaying the Login page
# and processing the submitted Login form.

@app.route("/login", methods=["GET", "POST"])
def login():

    # Check whether the user submitted the Login form.
    if request.method == "POST":

        # Get the email entered by the user.
        email = request.form["email"]

        # Get the password entered by the user.
        password = request.form["password"]

        # Connect to the SQLite database.
        connection = get_db_connection()

        # Find the user whose email matches the entered email.
        user = connection.execute(
            "SELECT * FROM users WHERE email = ?",
            (email,)
        ).fetchone()

        # Close the database connection.
        connection.close()

        # Check whether the user exists and password is correct.
        if user and check_password_hash(user["password"], password):

            # Store the logged-in user's ID in the session.
            session["user_id"] = user["id"]

            # Store the logged-in user's name in the session.
            session["user_name"] = user["name"]

            # Check the user's role.
            if user["role"] == "admin":

                # Admin users go to the Admin Dashboard.
                return redirect("/admin")

            else:

                # Normal students go to the normal Dashboard.
                return redirect("/dashboard")

        # Login failed, stay on the Login page.
        return render_template(
            "login.html",
            error="Invalid email or password. Please check your details or create a new account."
        )

    # Show the Login page for a normal GET request.
    return render_template("login.html")

