# Update a note belonging to the currently logged-in user
@app.route("/edit_note/<int:note_id>", methods=["GET", "POST"])
def edit_note(note_id):

    # Check whether the user is logged in
    if "user_id" not in session:
        return redirect("/login")

    # Connect to the SQLite database
    connection = get_db_connection()

    # Get only the selected note belonging to the logged-in user
    note = connection.execute(
        "SELECT * FROM notes WHERE id = ? AND user_id = ?",
        (note_id, session["user_id"])
    ).fetchone()

    # If the note does not exist or belongs to another user, return to Notes
    if note is None:
        connection.close()
        return redirect("/notes")

    # Check whether the user submitted the updated note
    if request.method == "POST":

        # Get the updated title
        title = request.form["title"]

        # Get the updated content
        content = request.form["content"]

        # Update only this user's selected note
        connection.execute(
            """
            UPDATE notes
            SET title = ?, content = ?
            WHERE id = ? AND user_id = ?
            """,
            (title, content, note_id, session["user_id"])
        )

        # Save the changes
        connection.commit()

        # Close the database connection
        connection.close()

        # Return to the Notes page
        return redirect("/notes")

    # Close the database connection
    connection.close()

    # Open the edit page with the existing note data
    return render_template("edit_note.html", note=note)

