# ===========================================================
# Toggle To-Do completion status
# This route changes a task between Pending and Completed.
# ===========================================================

@app.route("/complete_todo/<int:todo_id>")
def complete_todo(todo_id):

    # Check if the user is logged in
    if "user_id" not in session:
        return redirect("/login")

    # Connect to the database
    connection = get_db_connection()

    # Get the selected task of the current user
    todo = connection.execute(
        "SELECT completed FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, session["user_id"])
    ).fetchone()

    # If the task does not exist, return to To-Do page
    if todo is None:
        connection.close()
        return redirect("/todos")

    # Change 0 to 1 or 1 to 0
    new_status = 0 if todo["completed"] == 1 else 1

    # Update the task status
    connection.execute(
        "UPDATE todos SET completed = ? WHERE id = ? AND user_id = ?",
        (new_status, todo_id, session["user_id"])
    )

    # Save changes
    connection.commit()

    # Close database connection
    connection.close()

    # Return to To-Do page
    return redirect("/todos")



