# Register page open karne aur new account create karne ke liye route.
@app.route("/register", methods=["GET", "POST"])
def register():

    # Check whether the user submitted the registration form.
    if request.method == "POST":

        # Get user's name from the registration form.
        name = request.form["name"]

        # Get user's email from the registration form.
        email = request.form["email"]

        # Get user's password from the registration form.
        password = request.form["password"]

        # Connect to the SQLite database.
        connection = get_db_connection()

        # Check whether this email is already registered.
        existing_user = connection.execute(
            "SELECT id FROM users WHERE email = ?",
            (email,)
        ).fetchone()

        # If email already exists, stay on the same Register page.
        if existing_user:

            # Close the database connection.
            connection.close()

            # Show the Register page again with an error message.
            return render_template(
                "register.html",
                error="Email already registered. Please use another email."
            )

        # Convert password into a secure hash before storing it.
        hashed_password = generate_password_hash(password)

        # Insert the new user into the database.
        connection.execute(
            "INSERT INTO users (name, email, password) VALUES (?, ?, ?)",
            (name, email, hashed_password)
        )

        # Save the database changes.
        connection.commit()

        # Close the database connection.
        connection.close()

        # Registration successful, go to Login page.
        return render_template(
            "register.html",
            success="Account created successfully! You can now login."
        )

    # Show the Register page for a normal GET request.
    return render_template("register.html")


