    # This helper first tries Gemini and automatically switches to OpenRouter
# if Gemini is temporarily unavailable.
def generate_ai_answer(question):

    # Get the OpenRouter API key from the .env file.
    openrouter_api_key = os.getenv("OPENROUTER_API_KEY")

    try:
        # First try Gemini because it is our primary AI provider.
        response = client.models.generate_content(
            model="gemini-3.8-flash",
            contents=question
        )

        # Return Gemini's answer and the provider name.
        return response.text, "Gemini"

    except Exception as gemini_error:

        # Gemini failed, so now we automatically try OpenRouter.
        try:
            # Send the same question to OpenRouter.
            response = requests.post(
                "https://openrouter.ai/api/v1/chat/completions",

                # Send the OpenRouter API key securely in the request header.
                headers={
                    "Authorization": f"Bearer {openrouter_api_key}",
                    "Content-Type": "application/json"
                },

                # Use OpenRouter's free-model router.
                json={
                    "model": "openrouter/free",
                    "messages": [
                        {
                            "role": "user",
                            "content": question
                        }
                    ]
                },

                # Stop waiting if the OpenRouter server takes too long.
                timeout=30
            )

            # Raise an error if OpenRouter returns an HTTP error.
            response.raise_for_status()

            # Convert the response into JSON.
            data = response.json()

            # Get the generated answer from OpenRouter.
            answer = data["choices"][0]["message"]["content"]

            # Return OpenRouter's answer and provider name.
            return answer, "OpenRouter"

        except Exception as openrouter_error:

            # Both AI providers failed.
            return (
                "Sorry, both AI services are temporarily unavailable. "
                "Please try again after some time.",
                "Unavailable"
            )

# This route handles the AI Doubt Solver page.
# It uses Gemini first and automatically falls back to OpenRouter if needed.

@app.route("/ai_doubt", methods=["GET", "POST"])
def ai_doubt():

    # Check whether the student is logged in.
    if "user_id" not in session:
        return redirect("/login")

    # Store the formatted answer and AI provider name.
    answer = None
    provider = None

    # Check whether the student submitted a question.
    if request.method == "POST":

        # Get the student's question from the form.
        question = request.form["question"]

        # Generate the answer using Gemini or OpenRouter fallback.
        raw_answer, provider = generate_ai_answer(question)

        # Convert Markdown generated by the AI into HTML.
        answer = markdown.markdown(
            raw_answer,
            extensions=["extra"]
        )

    # Display the AI Doubt Solver page.
    return render_template(
        "ai_doubt.html",
        answer=answer,
        provider=provider
    )

# This route handles the Notes Summarizer.
# It takes the student's notes and sends them to our existing
# Gemini + OpenRouter automatic fallback system.

@app.route("/notes-summarizer", methods=["GET", "POST"])
def notes_summarizer():

    # Check whether the student is logged in.
    if "user_id" not in session:
        return redirect("/login")

    # Store the generated summary and provider name.
    summary = None
    provider = None

    # Check whether the student submitted notes.
    if request.method == "POST":

        # Get the notes entered by the student.
        notes = request.form["notes"]

        # Create a clear instruction for the AI.
        prompt = f"""
        Summarize the following study notes in simple and easy-to-understand language.

        Requirements:
        - Keep the important points.
        - Use headings where useful.
        - Use bullet points for important information.
        - Avoid unnecessary details.
        - Make the summary useful for a college student.

        Study Notes:
        {notes}
        """

        # Generate the summary using Gemini first
        # and OpenRouter automatically if Gemini fails.
        raw_summary, provider = generate_ai_answer(prompt)

        # Convert Markdown into HTML so headings,
        # bold text and bullet points display properly.
        summary = markdown.markdown(
            raw_summary,
            extensions=["extra"]
        )

    # Display the Notes Summarizer page.
    return render_template(
        "notes_summarizer.html",
        summary=summary,
        provider=provider
    )


# ========================================
# DATABASE CONNECTION
# ========================================

# SQLite database se connection establish karne wala function.
def get_db_connection():

    # database.db ke saath connection create kar rahe hain.
    connection = sqlite3.connect("database.db")

    # Database rows ko column names ke through access karne ki permission.
    connection.row_factory = sqlite3.Row

    # Database connection return kar rahe hain.
    return connection


# ========================================
# USERS TABLE
# ========================================

# This function creates the users table and adds an admin role system.
# Existing users are kept safe because we only add the role column
# if it does not already exist.

def create_users_table():

    # Connect to the SQLite database.
    connection = get_db_connection()

    # Create the users table if it does not already exist.
    connection.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )
    """)

    # Check the existing columns in the users table.
    columns = connection.execute(
        "PRAGMA table_info(users)"
    ).fetchall()

    # Get the names of all existing columns.
    column_names = [column["name"] for column in columns]

    # Add the role column only if it is missing.
    if "role" not in column_names:

        # Existing users will automatically get the default
        # role of 'student'.
        connection.execute("""
            ALTER TABLE users
            ADD COLUMN role TEXT NOT NULL DEFAULT 'student'
        """)

    # Save the database changes.
    connection.commit()

    # Close the database connection.
    connection.close()


# Create/update the users table when the application starts.
create_users_table()


# Application start hone par users table create kar rahe hain.
create_users_table()


