# This route displays all student accounts to the Admin.
# Only users with the 'admin' role can access this page.

@app.route("/admin/users")
def admin_users():

    # Check whether a user is logged in.
    if "user_id" not in session:
        return redirect("/login")

    # Connect to the database.
    connection = get_db_connection()

    # Check the role of the currently logged-in user.
    admin = connection.execute(
        "SELECT role FROM users WHERE id = ?",
        (session["user_id"],)
    ).fetchone()

    # If the user is not an admin, deny access.
    if admin is None or admin["role"] != "admin":
        connection.close()
        return redirect("/dashboard")

    # Get all student accounts.
    users = connection.execute(
        """
        SELECT id, name, email
        FROM users
        WHERE role = 'student'
        ORDER BY id DESC
        """
    ).fetchall()

    # Close the database connection.
    connection.close()

    # Send the student list to the Admin Users page.
    return render_template(
        "admin_users.html",
        users=users
    )


# This route completely deletes a student and all data
# belonging to that student from EduGenie.
# The Admin account itself cannot be deleted through this route.

@app.route("/admin/delete-user/<int:user_id>")
def admin_delete_user(user_id):

    # Check whether a user is logged in.
    if "user_id" not in session:
        return redirect("/login")

    # Connect to the database.
    connection = get_db_connection()

    # Check the role of the currently logged-in user.
    admin = connection.execute(
        "SELECT role FROM users WHERE id = ?",
        (session["user_id"],)
    ).fetchone()

    # Allow only Admin users to delete student accounts.
    if admin is None or admin["role"] != "admin":
        connection.close()
        return redirect("/dashboard")

    # Check that the selected account is actually a student.
    student = connection.execute(
        "SELECT id FROM users WHERE id = ? AND role = 'student'",
        (user_id,)
    ).fetchone()

    # Stop if the selected user does not exist
    # or is not a student.
    if student is None:
        connection.close()
        return redirect("/admin/users")

    # Delete all subjects belonging to the student.
    connection.execute(
        "DELETE FROM subjects WHERE user_id = ?",
        (user_id,)
    )

    # Delete all notes belonging to the student.
    connection.execute(
        "DELETE FROM notes WHERE user_id = ?",
        (user_id,)
    )

    # Delete all to-do tasks belonging to the student.
    connection.execute(
        "DELETE FROM todos WHERE user_id = ?",
        (user_id,)
    )

    # Delete all study planner records belonging to the student.
    connection.execute(
        "DELETE FROM study_plans WHERE user_id = ?",
        (user_id,)
    )

    # Delete all attendance records belonging to the student.
    connection.execute(
        "DELETE FROM attendance WHERE user_id = ?",
        (user_id,)
    )

    # Finally delete the student's account.
    connection.execute(
        "DELETE FROM users WHERE id = ? AND role = 'student'",
        (user_id,)
    )

    # Save all deletions together.
    connection.commit()

    # Close the database connection.
    connection.close()

    # Return to the Manage Users page.
    return redirect("/admin/users")


