# This route generates MCQ questions using the existing AI helper.
# It supports both Gemini and OpenRouter through generate_ai_answer().

@app.route("/quiz-generator", methods=["GET", "POST"])
def quiz_generator():

    # Check whether the student is logged in.
    if "user_id" not in session:
        return redirect("/login")

    # Process the submitted quiz form.
    if request.method == "POST":

        # Get the subject entered by the student.
        subject = request.form["subject"].strip()

        # Get the topic entered by the student.
        topic = request.form["topic"].strip()

        # Get the selected question count.
        question_count = int(request.form["question_count"])

        # Allow only the question counts provided in the form.
        if question_count not in [5, 10, 15]:
            return "Invalid question count."

        # Create instructions for the AI to generate MCQs.
        prompt = f"""
        Generate exactly {question_count} multiple-choice questions
        for a college student.

        Subject: {subject}
        Topic: {topic}

        Requirements:
        - Every question must have exactly four options.
        - Label the options A, B, C and D.
        - Only one option must be correct.
        - Include a short explanation for each answer.
        - Questions should be clear and educational.
        - Avoid duplicate questions.

        Return ONLY valid JSON in this exact structure:

        {{
            "questions": [
                {{
                    "question": "Question text",
                    "options": {{
                        "A": "Option A",
                        "B": "Option B",
                        "C": "Option C",
                        "D": "Option D"
                    }},
                    "correct_answer": "A",
                    "explanation": "Short explanation"
                }}
            ]
        }}

        Do not include Markdown code fences or extra text.
        """

        try:

            # Generate the quiz using Gemini or OpenRouter.
            raw_answer, provider = generate_ai_answer(prompt)

            # Find the JSON object in the AI response.
            json_match = re.search(
                r"\{.*\}",
                raw_answer,
                re.DOTALL
            )

            # Stop if the AI did not return valid JSON content.
            if not json_match:
                raise ValueError("AI did not return valid JSON.")

            # Convert the JSON response into Python data.
            quiz_data = json.loads(json_match.group())

            # Extract the generated questions.
            questions = quiz_data["questions"]

            # Verify that the AI generated the requested number.
            if len(questions) != question_count:
                raise ValueError("Incorrect number of questions generated.")

            # Validate the structure of every question.
            for question in questions:

                if not all(
                    key in question
                    for key in ["question", "options", "correct_answer", "explanation"]
                ):
                    raise ValueError("Question data is incomplete.")

                if set(question["options"].keys()) != {"A", "B", "C", "D"}:
                    raise ValueError("Each question must have four options.")

                if question["correct_answer"] not in ["A", "B", "C", "D"]:
                    raise ValueError("Invalid correct answer.")

# Save the generated quiz in the database.
# This keeps correct answers on the server instead of exposing them in HTML.

            connection = get_db_connection()

            cursor = connection.execute("""
                INSERT INTO quizzes (user_id, subject, topic, questions_json)
                VALUES (?, ?, ?, ?)
            """, (
                session["user_id"],
                subject,
                topic,
                json.dumps(quiz_data)
            ))

            # Get the unique ID of the newly created quiz.
            quiz_id = cursor.lastrowid

            connection.commit()
            connection.close()

            # Remove correct answers and explanations before displaying questions.
            display_questions = []

            for question in questions:
                display_questions.append({
                    "question": question["question"],
                    "options": question["options"]
                })

            # Render the quiz page with questions and options.
            return render_template(
                "quiz.html",
                quiz_id=quiz_id,
                subject=subject,
                topic=topic,
                questions=display_questions
            )


        except Exception as error:

            # Display a friendly message if quiz generation fails.
            return (
                "Sorry, the AI could not generate the quiz properly. "
                "Please try again."
            )

    # Display the Quiz Generator page.
    return render_template("quiz_generator.html")


# This route checks the student's submitted answers.
# It compares them with the correct answers stored in the database.

@app.route("/submit-quiz", methods=["POST"])
def submit_quiz():

    # Make sure the student is logged in.
    if "user_id" not in session:
        return redirect("/login")

    # Get the quiz ID submitted from the quiz form.
    quiz_id = request.form.get("quiz_id", type=int)

    if quiz_id is None:
        return "Invalid quiz submission."

    # Fetch the quiz belonging to the logged-in student.
    connection = get_db_connection()

    quiz = connection.execute("""
        SELECT * FROM quizzes
        WHERE id = ? AND user_id = ?
    """, (quiz_id, session["user_id"])).fetchone()

    connection.close()

    # Stop if the quiz does not exist or does not belong to this student.
    if quiz is None:
        return "Quiz not found."

    # Convert stored JSON into Python data.
    quiz_data = json.loads(quiz["questions_json"])
    questions = quiz_data["questions"]

    # Initialize score and result details.
    score = 0
    results = []

    # Check every submitted answer.
    for index, question in enumerate(questions):

        selected_answer = request.form.get(f"q_{index}")
        correct_answer = question["correct_answer"]

        # Check whether the selected answer is correct.
        is_correct = selected_answer == correct_answer

        if is_correct:
            score += 1

        # Store details needed for the result page.
        results.append({
            "question": question["question"],
            "options": question["options"],
            "selected_answer": selected_answer,
            "correct_answer": correct_answer,
            "is_correct": is_correct,
            "explanation": question["explanation"]
        })

    # Calculate percentage score.
    percentage = round((score / len(questions)) * 100)

    # Display the final quiz result.
    return render_template(
        "quiz_result.html",
        subject=quiz["subject"],
        topic=quiz["topic"],
        score=score,
        total=len(questions),
        percentage=percentage,
        results=results
    )




