# This route opens the Admin Dashboard and fetches
# real statistics from the EduGenie database.

@app.route("/admin")
def admin_dashboard():

    # Check whether a user is logged in.
    if "user_id" not in session:
        return redirect("/login")

    # Connect to the database.
    connection = get_db_connection()

    # Get the currently logged-in user's role.
    user = connection.execute(
        "SELECT role FROM users WHERE id = ?",
        (session["user_id"],)
    ).fetchone()

    # Check whether the logged-in user is an admin.
    if user is None or user["role"] != "admin":
        connection.close()
        return redirect("/dashboard")

    # Count all registered users.
    total_users = connection.execute(
        "SELECT COUNT(*) AS count FROM users WHERE role = 'student'"
    ).fetchone()["count"]

    # Count all subjects stored in the system.
    total_subjects = connection.execute(
        "SELECT COUNT(*) AS count FROM subjects"
    ).fetchone()["count"]

    # Count all notes stored in the system.
    total_notes = connection.execute(
        "SELECT COUNT(*) AS count FROM notes"
    ).fetchone()["count"]

    # Count all attendance records stored in the system.
    total_attendance = connection.execute(
        "SELECT COUNT(*) AS count FROM attendance"
    ).fetchone()["count"]

    # Close the database connection.
    connection.close()

    # Send the statistics to the Admin Dashboard.
    return render_template(
        "admin_dashboard.html",
        total_users=total_users,
        total_subjects=total_subjects,
        total_notes=total_notes,
        total_attendance=total_attendance
    )

